enum { HK_REGION, HK_FULL, HK_WINDOW, HK_MONITOR, HK_REPEAT, HK_HISTORY, HK_COUNT };
static const PCWSTR kHotkeyKeys[HK_COUNT] = {L"regionHotkey", L"fullscreenHotkey", L"windowHotkey",
                                             L"monitorHotkey", L"repeatHotkey",     L"historyHotkey"};

struct Config {
    std::wstring hotkeys[HK_COUNT];
    bool stepAside = true;
    bool catchKeys = true;
    bool histPeek = true;
    bool copy = true, save = true, toast = true, cursor = true, sound = true;
    std::wstring soundFile;
    int toastSeconds = 3;
    // The preview card.
    std::wstring toastPos = L"br", toastAnim = L"slide", toastClick = L"open", toastRight = L"folder", toastMiddle = L"copy";
    int toastAnimMs = 220, toastScale = 100;
    bool toastGlass = true, toastGlow = true, toastText = true, toastPause = true;
    std::wstring folder = L"G:\\Gallery", subfolder = L"day", format = L"png";
    int jpgQuality = 92;
    int dim = 45;
    bool snapWindows = true, snapControls = true, showSize = true, crossLines = false;
    bool magnifier = true, magGrid = true;
    int magPixels = 15, magZoom = 10;
    COLORREF accent1 = RGB(0x89, 0xB4, 0xFA), accent2 = RGB(0xCB, 0xA6, 0xF7);
    bool trayIcon = true;
    bool takeOverWss = true;
    bool drawBar = true, keepRegionOpen = false, drawShadow = true, drawOutline = false;
    COLORREF drawColor = RGB(0xF3, 0x8B, 0xA8);
    int drawSize = 4;
    // The drawing tools, ShareX's options.
    std::wstring barPos = L"top";
    COLORREF palette[8] = {RGB(0xF3, 0x8B, 0xA8), RGB(0xFA, 0xB3, 0x87), RGB(0xF9, 0xE2, 0xAF), RGB(0xA6, 0xE3, 0xA1),
                           RGB(0x89, 0xB4, 0xFA), RGB(0xCB, 0xA6, 0xF7), RGB(0xFF, 0xFF, 0xFF), RGB(0x11, 0x11, 0x1B)};
    int boxRadius = 6;
    std::wstring fill = L"none";  // none, shade (the pen color, see-through), color (fillColor)
    COLORREF fillColor = RGB(0x1E, 0x1E, 0x2E);
    int fillOpacity = 25;
    std::wstring lineStyle = L"solid", arrowHeads = L"end", arrowStyle = L"filled";
    int arrowSize = 100;
    std::wstring textFont = L"FiraCode Nerd Font", textBox = L"none";
    bool textBold = true, textItalic = false;
    int textScale = 100;
    std::wstring stepStyle = L"numbers";
    int stepStart = 1, stepScale = 100;
    COLORREF markColor = RGB(0xF9, 0xE2, 0xAF);
    bool markPen = false;
    int markOpacity = 38;
    int blurStrength = 12, pixelSize = 12;
    COLORREF shadowColor = RGB(0, 0, 0);
    int shadowOpacity = 45, shadowOffset = 3, shadowSoftness = 3;
    std::wstring outlineColor = L"contrast";
    int outlineWidth = 3;
    COLORREF textColor = RGB(0xFF, 0xFF, 0xFF), stepColor = RGB(0xF3, 0x8B, 0xA8);
    bool textOutline = true, arrowCurved = false, rememberBar = true;
    std::wstring magnifyZoom = L"2", magnifyShape = L"box", spotlightShape = L"box";
    int spotlightDim = 60;
};

static Config g_cfg;

static void LoadSettings() {
    Config c;
    for (int i = 0; i < HK_COUNT; i++) c.hotkeys[i] = Trim(ReadStr(kHotkeyKeys[i]));
    c.stepAside = Wh_GetIntSetting(L"stepAside") != 0;
    c.copy = Wh_GetIntSetting(L"copyToClipboard") != 0;
    c.save = Wh_GetIntSetting(L"saveToFile") != 0;
    c.toast = Wh_GetIntSetting(L"showToast") != 0;
    c.toastSeconds = Clamp(Wh_GetIntSetting(L"toastSeconds"), 1, 10);
    c.cursor = Wh_GetIntSetting(L"captureCursor") != 0;
    c.sound = Wh_GetIntSetting(L"playSound") != 0;
    c.soundFile = Trim(ReadStr(L"soundFile"));
    while (c.soundFile.size() >= 2 && c.soundFile.front() == L'"' && c.soundFile.back() == L'"')
        c.soundFile = c.soundFile.substr(1, c.soundFile.size() - 2);
    c.catchKeys = Wh_GetIntSetting(L"catchKeys") != 0;
    c.histPeek = Wh_GetIntSetting(L"histPeek") != 0;
    c.toastPos = OneOf(ReadStr(L"toastPosition"), {L"br", L"bl", L"tr", L"tl"});
    c.toastAnim = OneOf(ReadStr(L"toastAnimation"), {L"slide", L"fade", L"grow", L"none"});
    c.toastAnimMs = Clamp(Wh_GetIntSetting(L"toastAnimationMs"), 80, 800);
    c.toastScale = Clamp(Wh_GetIntSetting(L"toastSize"), 75, 160);
    c.toastGlass = Wh_GetIntSetting(L"toastGlass") != 0;
    c.toastGlow = Wh_GetIntSetting(L"toastHoverGlow") != 0;
    c.toastText = Wh_GetIntSetting(L"toastShowText") != 0;
    c.toastPause = Wh_GetIntSetting(L"toastPauseOnHover") != 0;
    c.toastClick = OneOf(ReadStr(L"toastClick"), {L"open", L"folder", L"copy", L"edit", L"close"});
    c.toastRight = OneOf(ReadStr(L"toastRightClick"), {L"folder", L"open", L"copy", L"edit", L"close"});
    c.toastMiddle = OneOf(ReadStr(L"toastMiddleClick"), {L"copy", L"open", L"folder", L"edit", L"close"});
    c.folder = Trim(ReadStr(L"saveFolder"));
    while (c.folder.size() >= 2 && c.folder.front() == L'"' && c.folder.back() == L'"')
        c.folder = c.folder.substr(1, c.folder.size() - 2);
    while (c.folder.size() > 3 && (c.folder.back() == L'\\' || c.folder.back() == L'/')) c.folder.pop_back();
    if (c.folder.empty()) c.folder = L"G:\\Gallery";
    c.subfolder = OneOf(ReadStr(L"subfolder"), {L"day", L"app", L"none"});
    c.format = OneOf(ReadStr(L"fileFormat"), {L"png", L"jpg"});
    c.jpgQuality = Clamp(Wh_GetIntSetting(L"jpgQuality"), 50, 100);
    c.dim = Clamp(Wh_GetIntSetting(L"dimOpacity"), 0, 85);
    c.snapWindows = Wh_GetIntSetting(L"snapWindows") != 0;
    c.snapControls = Wh_GetIntSetting(L"snapControls") != 0;
    c.showSize = Wh_GetIntSetting(L"showSize") != 0;
    c.crossLines = Wh_GetIntSetting(L"crosshairLines") != 0;
    c.magnifier = Wh_GetIntSetting(L"magnifier") != 0;
    c.magPixels = Clamp(Wh_GetIntSetting(L"magnifierPixels"), 7, 31) | 1;  // Odd, so one pixel is the middle.
    c.magZoom = Clamp(Wh_GetIntSetting(L"magnifierZoom"), 4, 24);
    c.magGrid = Wh_GetIntSetting(L"magnifierGrid") != 0;
    COLORREF col;
    if (ParseHex(ReadStr(L"accentFrom"), col)) c.accent1 = col;
    if (ParseHex(ReadStr(L"accentTo"), col)) c.accent2 = col;
    c.trayIcon = Wh_GetIntSetting(L"settingsTrayIcon") != 0;
    c.takeOverWss = Wh_GetIntSetting(L"takeOverSnippingKey") != 0;
    c.drawBar = Wh_GetIntSetting(L"drawBar") != 0;
    c.keepRegionOpen = Wh_GetIntSetting(L"keepRegionOpen") != 0;
    if (ParseHex(ReadStr(L"drawColor"), col)) c.drawColor = col;
    c.drawSize = Clamp(Wh_GetIntSetting(L"drawSize"), 1, 20);
    c.drawShadow = Wh_GetIntSetting(L"drawShadow") != 0;
    c.drawOutline = Wh_GetIntSetting(L"drawOutline") != 0;
    c.barPos = OneOf(ReadStr(L"barPosition"), {L"top", L"bottom"});
    {
        // Up to 8 hex colors split by spaces, commas or semicolons; missing ones keep the default.
        std::wstring pal = ReadStr(L"barColors");
        int n = 0;
        size_t i = 0;
        while (i < pal.size() && n < 8) {
            while (i < pal.size() && (pal[i] == L' ' || pal[i] == L',' || pal[i] == L';')) i++;
            size_t j = i;
            while (j < pal.size() && pal[j] != L' ' && pal[j] != L',' && pal[j] != L';') j++;
            if (j > i && ParseHex(pal.substr(i, j - i), col)) c.palette[n++] = col;
            i = j;
        }
    }
    c.boxRadius = Clamp(Wh_GetIntSetting(L"boxCornerRadius"), 0, 60);
    c.fill = OneOf(ReadStr(L"boxFill"), {L"none", L"shade", L"color"});
    if (ParseHex(ReadStr(L"fillColor"), col)) c.fillColor = col;
    c.fillOpacity = Clamp(Wh_GetIntSetting(L"fillOpacity"), 5, 100);
    c.lineStyle = OneOf(ReadStr(L"lineStyle"), {L"solid", L"dash", L"dot"});
    c.arrowHeads = OneOf(ReadStr(L"arrowHeads"), {L"end", L"start", L"both"});
    c.arrowStyle = OneOf(ReadStr(L"arrowStyle"), {L"filled", L"notched", L"open", L"line"});
    c.arrowSize = Clamp(Wh_GetIntSetting(L"arrowHeadSize"), 50, 250);
    c.textFont = Trim(ReadStr(L"textFont"));
    if (c.textFont.empty()) c.textFont = L"FiraCode Nerd Font";
    c.textBold = Wh_GetIntSetting(L"textBold") != 0;
    c.textItalic = Wh_GetIntSetting(L"textItalic") != 0;
    c.textScale = Clamp(Wh_GetIntSetting(L"textSize"), 50, 300);
    c.textBox = OneOf(ReadStr(L"textBackground"), {L"none", L"pen", L"dark"});
    c.stepStyle = OneOf(ReadStr(L"stepStyle"), {L"numbers", L"letters", L"lettersLower", L"roman", L"romanLower"});
    c.stepStart = Clamp(Wh_GetIntSetting(L"stepStart"), 1, 99);
    c.stepScale = Clamp(Wh_GetIntSetting(L"stepSize"), 50, 300);
    c.markPen = Wh_GetIntSetting(L"highlighterUsesPen") != 0;
    if (ParseHex(ReadStr(L"highlighterColor"), col)) c.markColor = col;
    c.markOpacity = Clamp(Wh_GetIntSetting(L"highlighterOpacity"), 10, 80);
    c.blurStrength = Clamp(Wh_GetIntSetting(L"blurStrength"), 2, 40);
    c.pixelSize = Clamp(Wh_GetIntSetting(L"pixelSize"), 3, 60);
    if (ParseHex(ReadStr(L"shadowColor"), col)) c.shadowColor = col;
    c.shadowOpacity = Clamp(Wh_GetIntSetting(L"shadowOpacity"), 5, 100);
    c.shadowOffset = Clamp(Wh_GetIntSetting(L"shadowOffset"), 0, 20);
    c.shadowSoftness = Clamp(Wh_GetIntSetting(L"shadowSoftness"), 1, 8);
    c.outlineColor = OneOf(ReadStr(L"outlineColor"), {L"contrast", L"white", L"black"});
    c.outlineWidth = Clamp(Wh_GetIntSetting(L"outlineWidth"), 1, 10);
    if (ParseHex(ReadStr(L"textColor"), col)) c.textColor = col;
    c.textOutline = Wh_GetIntSetting(L"textOutline") != 0;
    if (ParseHex(ReadStr(L"stepColor"), col)) c.stepColor = col;
    c.arrowCurved = Wh_GetIntSetting(L"arrowCurved") != 0;
    c.magnifyZoom = OneOf(ReadStr(L"magnifyZoom"), {L"2", L"1.5", L"3", L"4", L"6"});
    c.magnifyShape = OneOf(ReadStr(L"magnifyShape"), {L"box", L"circle"});
    c.spotlightDim = Clamp(Wh_GetIntSetting(L"spotlightDim"), 30, 90);
    c.spotlightShape = OneOf(ReadStr(L"spotlightShape"), {L"box", L"circle"});
    c.rememberBar = Wh_GetIntSetting(L"rememberBar") != 0;
    g_cfg = c;
}

// ---------------------------------------------------------------------------
// Pictures: BGRA pixels, top-down, alpha always 255.
// ---------------------------------------------------------------------------

struct Shot {
    int x = 0, y = 0, w = 0, h = 0;  // Screen position and size.
    std::vector<uint32_t> px;
};

static bool CaptureRect(const RECT& r, bool cursor, Shot& out) {
    int w = r.right - r.left, h = r.bottom - r.top;
    if (w <= 0 || h <= 0) return false;
    HDC sdc = GetDC(nullptr);
    HDC mdc = CreateCompatibleDC(sdc);
    BITMAPINFO bi{};
    bi.bmiHeader.biSize = sizeof(bi.bmiHeader);
    bi.bmiHeader.biWidth = w;
    bi.bmiHeader.biHeight = -h;
    bi.bmiHeader.biPlanes = 1;
    bi.bmiHeader.biBitCount = 32;
    bi.bmiHeader.biCompression = BI_RGB;
    void* bits = nullptr;
    HBITMAP hb = CreateDIBSection(mdc, &bi, DIB_RGB_COLORS, &bits, nullptr, 0);
    bool ok = false;
    if (hb) {
        HGDIOBJ old = SelectObject(mdc, hb);
        ok = BitBlt(mdc, 0, 0, w, h, sdc, r.left, r.top, SRCCOPY | CAPTUREBLT) != 0;
        if (ok && cursor) {
            CURSORINFO ci{sizeof(ci)};
            if (GetCursorInfo(&ci) && (ci.flags & CURSOR_SHOWING) && ci.hCursor) {
                ICONINFO ii{};
                if (GetIconInfo(ci.hCursor, &ii)) {
                    DrawIconEx(mdc, ci.ptScreenPos.x - (int)ii.xHotspot - r.left,
                               ci.ptScreenPos.y - (int)ii.yHotspot - r.top, ci.hCursor, 0, 0, 0, nullptr, DI_NORMAL);
                    if (ii.hbmMask) DeleteObject(ii.hbmMask);
                    if (ii.hbmColor) DeleteObject(ii.hbmColor);
                }
            }
        }
        GdiFlush();
        if (ok) {
            out.x = r.left;
            out.y = r.top;
            out.w = w;
            out.h = h;
            out.px.assign((uint32_t*)bits, (uint32_t*)bits + (size_t)w * h);
            for (auto& v : out.px) v |= 0xFF000000;
        }
        SelectObject(mdc, old);
        DeleteObject(hb);
    }
    DeleteDC(mdc);
    ReleaseDC(nullptr, sdc);
    return ok;
}

static Shot Crop(const Shot& s, RECT r) {
    Shot o;
    r.left = std::max(r.left, 0L);
    r.top = std::max(r.top, 0L);
    r.right = std::min(r.right, (LONG)s.w);
    r.bottom = std::min(r.bottom, (LONG)s.h);
    if (r.right <= r.left || r.bottom <= r.top) return o;
    o.x = s.x + r.left;
    o.y = s.y + r.top;
    o.w = r.right - r.left;
    o.h = r.bottom - r.top;
    o.px.resize((size_t)o.w * o.h);
    for (int y = 0; y < o.h; y++)
        memcpy(&o.px[(size_t)y * o.w], &s.px[(size_t)(r.top + y) * s.w + r.left], (size_t)o.w * 4);
    return o;
}

// Box filter, for the preview card.
static Shot Downscale(const Shot& s, int maxW, int maxH) {
    double k = std::min({1.0, (double)maxW / s.w, (double)maxH / s.h});
    if (k >= 1.0) return s;
    Shot o;
    o.w = std::max(1, (int)std::lround(s.w * k));
    o.h = std::max(1, (int)std::lround(s.h * k));
    o.px.resize((size_t)o.w * o.h);
    for (int y = 0; y < o.h; y++) {
        int y0 = (int)((int64_t)y * s.h / o.h), y1 = std::max(y0 + 1, (int)((int64_t)(y + 1) * s.h / o.h));
        for (int x = 0; x < o.w; x++) {
            int x0 = (int)((int64_t)x * s.w / o.w), x1 = std::max(x0 + 1, (int)((int64_t)(x + 1) * s.w / o.w));
            uint64_t r = 0, g = 0, b = 0, n = (uint64_t)(x1 - x0) * (y1 - y0);
            for (int yy = y0; yy < y1; yy++) {
                const uint32_t* row = &s.px[(size_t)yy * s.w];
                for (int xx = x0; xx < x1; xx++) {
                    uint32_t v = row[xx];
                    r += (v >> 16) & 0xFF;
                    g += (v >> 8) & 0xFF;
                    b += v & 0xFF;
                }
            }
            o.px[(size_t)y * o.w + x] = 0xFF000000 | (uint32_t)(r / n) << 16 | (uint32_t)(g / n) << 8 | (uint32_t)(b / n);
        }
    }
    return o;
}

static HRESULT EncodeFile(const Shot& s, const std::wstring& path, bool jpg, int quality) {
    Ptr<IWICImagingFactory> f;
    Ptr<IWICBitmap> bmp;
    Ptr<IWICFormatConverter> conv;
    Ptr<IWICStream> st;
    Ptr<IWICBitmapEncoder> enc;
    Ptr<IWICBitmapFrameEncode> fr;
    Ptr<IPropertyBag2> bag;
    HRESULT hr = CoCreateInstance(CLSID_WICImagingFactory, nullptr, CLSCTX_INPROC_SERVER, IID_IWICImagingFactory,
                                  (void**)f.put());
    if (SUCCEEDED(hr))
        hr = f->CreateBitmapFromMemory(s.w, s.h, GUID_WICPixelFormat32bppBGR, s.w * 4, (UINT)(s.px.size() * 4),
                                       (BYTE*)s.px.data(), bmp.put());
    if (SUCCEEDED(hr)) hr = f->CreateFormatConverter(conv.put());
    if (SUCCEEDED(hr))
        hr = conv->Initialize(bmp.p, GUID_WICPixelFormat24bppBGR, WICBitmapDitherTypeNone, nullptr, 0,
                              WICBitmapPaletteTypeCustom);
    if (SUCCEEDED(hr)) hr = f->CreateStream(st.put());
    if (SUCCEEDED(hr)) hr = st->InitializeFromFilename(path.c_str(), GENERIC_WRITE);
    if (FAILED(hr)) return hr;
    hr = f->CreateEncoder(jpg ? GUID_ContainerFormatJpeg : GUID_ContainerFormatPng, nullptr, enc.put());
    if (SUCCEEDED(hr)) hr = enc->Initialize(st.p, WICBitmapEncoderNoCache);
    if (SUCCEEDED(hr)) hr = enc->CreateNewFrame(fr.put(), bag.put());
    if (SUCCEEDED(hr) && jpg && bag) {
        PROPBAG2 opt{};
        opt.pstrName = (LPOLESTR)L"ImageQuality";
        VARIANT v;
        VariantInit(&v);
        v.vt = VT_R4;
        v.fltVal = quality / 100.0f;
        bag->Write(1, &opt, &v);
    }
    if (SUCCEEDED(hr)) hr = fr->Initialize(bag.p);
    if (SUCCEEDED(hr)) hr = fr->SetSize(s.w, s.h);
    WICPixelFormatGUID pf = GUID_WICPixelFormat24bppBGR;
    if (SUCCEEDED(hr)) hr = fr->SetPixelFormat(&pf);
    if (SUCCEEDED(hr)) hr = fr->WriteSource(conv.p, nullptr);
    if (SUCCEEDED(hr)) hr = fr->Commit();
    if (SUCCEEDED(hr)) hr = enc->Commit();
    st.Reset();
    if (FAILED(hr)) DeleteFileW(path.c_str());
    return hr;
}

// ---------------------------------------------------------------------------
// Names: "Discord 4.05 pm.png"
// ---------------------------------------------------------------------------

static std::wstring CleanName(std::wstring s) {
    for (auto& c : s)
        if (c < 32 || wcschr(L"<>:\"/\\|?*", c)) c = L' ';
    s = Trim(s);
    std::wstring o;
    for (wchar_t c : s)
        if (!(c == L' ' && !o.empty() && o.back() == L' ')) o += c;
    while (!o.empty() && (o.back() == L'.' || o.back() == L' ')) o.pop_back();
    if (o.size() > 40) o = Trim(o.substr(0, 40));
    return o;
}

static std::wstring FileDescription(const std::wstring& path) {
    DWORD dummy = 0, size = GetFileVersionInfoSizeW(path.c_str(), &dummy);
    if (!size) return {};
    std::vector<BYTE> data(size);
    if (!GetFileVersionInfoW(path.c_str(), 0, size, data.data())) return {};
    struct Lang {
        WORD lang, cp;
    }* langs = nullptr;
    UINT len = 0;
    std::vector<std::wstring> keys;
    if (VerQueryValueW(data.data(), L"\\VarFileInfo\\Translation", (void**)&langs, &len) && len >= sizeof(Lang)) {
        WCHAR k[64];
        swprintf_s(k, L"\\StringFileInfo\\%04x%04x\\FileDescription", langs[0].lang, langs[0].cp);
        keys.push_back(k);
    }
    keys.push_back(L"\\StringFileInfo\\040904b0\\FileDescription");
    keys.push_back(L"\\StringFileInfo\\040904e4\\FileDescription");
    for (auto& k : keys) {
        WCHAR* text = nullptr;
        if (VerQueryValueW(data.data(), k.c_str(), (void**)&text, &len) && text && len > 1) return Trim(text);
    }
    return {};
}

// The app a window belongs to, as people call it: the exe's description, or the exe name.
static std::wstring AppName(HWND hwnd) {
    static std::mutex lock;
    static std::unordered_map<std::wstring, std::wstring> cache;
    if (!hwnd) return L"Screenshot";
    hwnd = GetAncestor(hwnd, GA_ROOT);
    if (!hwnd || IsShellWindow(hwnd)) return L"Screenshot";
    DWORD pid = 0;
    GetWindowThreadProcessId(hwnd, &pid);
    std::wstring path;
    if (HANDLE h = OpenProcess(PROCESS_QUERY_LIMITED_INFORMATION, FALSE, pid)) {
        WCHAR buf[MAX_PATH * 2];
        DWORD n = ARRAYSIZE(buf);
        if (QueryFullProcessImageNameW(h, 0, buf, &n)) path.assign(buf, n);
        CloseHandle(h);
    }
    std::wstring exe = path.substr(path.find_last_of(L'\\') == std::wstring::npos ? 0 : path.find_last_of(L'\\') + 1);
    // Store apps all run in one frame host: their title is the useful name.
    if (!_wcsicmp(exe.c_str(), L"ApplicationFrameHost.exe")) {
        WCHAR title[128]{};
        GetWindowTextW(hwnd, title, 128);
        std::wstring t = CleanName(title);
        return t.empty() ? L"Screenshot" : t;
    }
    if (!_wcsicmp(exe.c_str(), L"explorer.exe")) return L"File Explorer";
    std::lock_guard<std::mutex> g(lock);
    auto it = cache.find(path);
    if (it != cache.end()) return it->second;
    std::wstring name = path.empty() ? L"" : CleanName(FileDescription(path));
    if (name.empty()) {
        name = exe;
        if (name.size() > 4 && !_wcsicmp(name.c_str() + name.size() - 4, L".exe")) name.resize(name.size() - 4);
        name = CleanName(name);
    }
    if (name.empty()) name = L"Screenshot";
    cache[path] = name;
    return name;
}

static std::wstring TimeStamp(const SYSTEMTIME& t) {
    int h = t.wHour % 12 == 0 ? 12 : t.wHour % 12;
    WCHAR buf[32];
    swprintf_s(buf, L"%d.%02d %s", h, t.wMinute, t.wHour < 12 ? L"am" : L"pm");
    return buf;
}

static std::wstring ExpandPath(const std::wstring& p) {
    WCHAR buf[MAX_PATH * 2]{};
    DWORD n = ExpandEnvironmentStringsW(p.c_str(), buf, ARRAYSIZE(buf));
    return n && n <= ARRAYSIZE(buf) ? std::wstring(buf) : p;
}

